import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
CASES={9:('多智能体编排','delegation','原生子 Agent 派生与工具执行通过率','Ten sequential actual native child spawns per framework through HTTP agents. The scripted model fixes the plan; child agents perform one native terminal call. Verify accepted/completed native delegation response, actual tool start/end, and child final model response.'),21:('AI 网关','gateway','HTTP 入口至工具执行与回复通过率','Ten authenticated actual native /v1/chat/completions requests per framework, each requiring one native terminal tool; check HTTP reply and independent actual tool execution events.'),2:('端云调度','ssh','指定 SSH 端点执行与结果归属通过率','Native SSH transports against two dedicated loopback SSH endpoints. Ten actual remote write/read commands alternate endpoint selection.'),18:('分布式智能体资源管理','ssh','双端点资源读取与汇总通过率','Each case reads a distinct JSON resource through each native SSH connection and verifies endpoint identities and combined value; 10 repetitions.'),13:('通信管理','mcp','MCP schema 与内容往返通过率','Five fresh stdio MCP sessions per framework; two tool calls per session; validates discovery schema, ASCII, Chinese/emoji, newline/quote and 10 KB payload round trips. Explicit session recreation, not automatic reconnection.'),22:('屏幕自动驾驶','browser','固定网页表单操作验收通过率','Ten local web form tasks using native browser control modules: navigation, input, click and Saved state; independent HTTP server events verify Unicode reference and numeric quantity. Fixed action plans, no real-model or visual reasoning.')}
for row,(title,kind,metric,scope) in CASES.items():
 paths={f:ROOT/f'raw/extended-integration/{f}-{kind}.json' for f in ['openclaw','hermes']}
 if not all(p.exists() for p in paths.values()):continue
 data={'row':row,'title':title,'metric':metric,'unit':'%','direction':'higher','scope':scope,'limitations':['Functional integration under a fixed fixture and pinned commits; not a performance or broad capability ranking.'],'status':'measured','frameworks':{}}
 if row in [2,18]:data['limitations']+=['Endpoints are co-located on the same physical host with separate ports and fixture directories; no physical cloud, network latency, scheduler, or endpoint isolation claim.']
 if row==9:data['limitations']+=['One child per parent, fixed plan, terminal-only tasks; parent result synthesis, multi-child scheduling, distributed agents and cancellation were not measured. OpenClaw returns accepted plus asynchronous completion; Hermes API-server delegates synchronously. Elapsed times are diagnostics and are not compared.']
 if row==21:data['limitations']+=['Only the native OpenAI-compatible HTTP entrance was measured; messaging channels, throughput, authentication strength and gateway availability were not measured.']
 if row==13:data['limitations']+=['Only stdio MCP was measured; HTTP/SSE/A2A/ACP and unexpected disconnect recovery were not measured.']
 if row==22:data['limitations']+=['OpenClaw browser production Playwright owners and Hermes raw-CDP tool are different native control surfaces; this measures lower-level browser mechanism operation, not agent task planning, desktop automation or visual perception.']
 for f,p in paths.items():
  native=json.loads(p.read_text());records=[v for v in native['records'] if v.get('row',row)==row];values=[int(v['passed']) for v in records];data['frameworks'][f]={'values':values,'passed':sum(values),'total':len(values),'entrypoints':native['entrypoints'],'evidence':[str(p.relative_to(ROOT))]+(['raw/extended-integration/delegation-audit.json'] if row==9 else ['raw/extended-integration/browser-events.jsonl'] if row==22 else [])}
 (ROOT/f'results/extended-row-{row:02}.json').write_text(json.dumps(data,indent=2,ensure_ascii=False));print(row,{f:v['passed'] for f,v in data['frameworks'].items()})
